'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let pos = 0;

const E = data[pos++];
const R = data[pos++];

const graph = Array.from({ length: E }, () => []);
const edgeU = new Int32Array(R);
const edgeV = new Int32Array(R);
const edgeW = new Int32Array(R);

for (let i = 0; i < R; i++) {
  const u = data[pos++] - 1;
  const v = data[pos++] - 1;
  const w = data[pos++];
  edgeU[i] = u;
  edgeV[i] = v;
  edgeW[i] = w;
  graph[u].push([v, w, i]);
  graph[v].push([u, w, i]);
}

// Find bridges with an iterative DFS.
const tin = new Int32Array(E);
tin.fill(-1);
const low = new Int32Array(E);
const parent = new Int32Array(E);
parent.fill(-1);
const parentEdge = new Int32Array(E);
parentEdge.fill(-1);
const nextIndex = new Int32Array(E);
const isBridge = new Uint8Array(R);
let timer = 0;

for (let root = 0; root < E; root++) {
  if (tin[root] !== -1) continue;

  const stack = [root];
  tin[root] = low[root] = timer++;

  while (stack.length) {
    const u = stack[stack.length - 1];

    if (nextIndex[u] < graph[u].length) {
      const [v, , edgeId] = graph[u][nextIndex[u]++];

      if (edgeId === parentEdge[u]) continue;

      if (tin[v] === -1) {
        parent[v] = u;
        parentEdge[v] = edgeId;
        tin[v] = low[v] = timer++;
        stack.push(v);
      } else {
        low[u] = Math.min(low[u], tin[v]);
      }
    } else {
      stack.pop();
      if (parent[u] !== -1) {
        const p = parent[u];
        low[p] = Math.min(low[p], low[u]);
        if (low[u] > tin[p]) isBridge[parentEdge[u]] = 1;
      }
    }
  }
}

// Each connected component of non-bridge edges is one cycle.
const visitedVertex = new Uint8Array(E);
const visitedEdge = new Uint8Array(R);
const cycles = [];

for (let start = 0; start < E; start++) {
  if (visitedVertex[start]) continue;

  let hasCycleEdge = false;
  for (const [, , edgeId] of graph[start]) {
    if (!isBridge[edgeId]) {
      hasCycleEdge = true;
      break;
    }
  }
  if (!hasCycleEdge) continue;

  const vertices = [];
  const stack = [start];
  visitedVertex[start] = 1;
  let length = 0;

  while (stack.length) {
    const u = stack.pop();
    vertices.push(u);

    for (const [v, , edgeId] of graph[u]) {
      if (isBridge[edgeId]) continue;
      if (!visitedEdge[edgeId]) {
        visitedEdge[edgeId] = 1;
        length += edgeW[edgeId];
      }
      if (!visitedVertex[v]) {
        visitedVertex[v] = 1;
        stack.push(v);
      }
    }
  }

  cycles.push({ vertices, length });
}

class MinHeap {
  constructor() {
    this.nodes = [];
    this.values = [];
  }

  push(node, value) {
    let i = this.nodes.length;
    this.nodes.push(node);
    this.values.push(value);

    while (i > 0) {
      const p = (i - 1) >> 1;
      if (this.values[p] <= value) break;
      this.nodes[i] = this.nodes[p];
      this.values[i] = this.values[p];
      i = p;
    }
    this.nodes[i] = node;
    this.values[i] = value;
  }

  pop() {
    const node = this.nodes[0];
    const value = this.values[0];
    const lastNode = this.nodes.pop();
    const lastValue = this.values.pop();

    if (this.nodes.length) {
      let i = 0;
      while (true) {
        let child = i * 2 + 1;
        if (child >= this.nodes.length) break;
        if (child + 1 < this.nodes.length && this.values[child + 1] < this.values[child]) {
          child++;
        }
        if (this.values[child] >= lastValue) break;
        this.nodes[i] = this.nodes[child];
        this.values[i] = this.values[child];
        i = child;
      }
      this.nodes[i] = lastNode;
      this.values[i] = lastValue;
    }

    return [node, value];
  }

  get size() {
    return this.nodes.length;
  }
}

const K = data[pos++];
const output = [];

for (let q = 0; q < K; q++) {
  const source = data[pos++] - 1;
  const trainLength = data[pos++];

  const dist = new Float64Array(E);
  dist.fill(Infinity);
  dist[source] = 0;

  const heap = new MinHeap();
  heap.push(source, 0);

  while (heap.size) {
    const [u, d] = heap.pop();
    if (d !== dist[u]) continue;

    for (const [v, w] of graph[u]) {
      const nd = d + w;
      if (nd < dist[v]) {
        dist[v] = nd;
        heap.push(v, nd);
      }
    }
  }

  let answer = Infinity;
  for (const cycle of cycles) {
    if (cycle.length < trainLength) continue;

    let nearest = Infinity;
    for (const v of cycle.vertices) {
      if (dist[v] < nearest) nearest = dist[v];
    }

    answer = Math.min(answer, cycle.length + 2 * nearest);
  }

  output.push(answer === Infinity ? '-1' : String(answer));
}

console.log(output.join('\n'));
